{
  "items": [
    {
      "title": "German Bundestag Open Data – Parliamentary Proceedings, Members and Voting Records",
      "url_or_doi": "https://www.bundestag.de/services/opendata/",
      "justification": "Official open data portal of the German Bundestag. Provides machine-readable parliamentary documents, plenary proceedings, biographies of members of parliament, and recorded voting results. Covers parliamentary activity throughout the 2010s and 2020s. Particularly useful for studying legislative processes, parliamentary representation, political parties, government accountability, and institutional decision-making in Germany."
    },
    {
      "title": "German Longitudinal Election Study (GLES) – Data and Documentation",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "A major collection of German electoral research datasets maintained by GESIS. Includes surveys of voters, candidates, political preferences, party identification, electoral participation, and political attitudes. Covers the federal elections of 2013, 2017, 2021, and 2025, alongside longitudinal studies. Particularly valuable for examining political behavior, democratic participation, party competition, and changes in Germany's political system."
    },
    {
      "title": "The Federal Returning Officer – German Federal Election 2025 Open Data",
      "url_or_doi": "https://www.bundeswahlleiterin.de/bundestagswahlen/2025/ergebnisse/opendata.html",
      "justification": "Official election dataset published by Germany's Federal Returning Officer (Bundeswahlleiterin). Contains detailed results of the 2025 federal parliamentary election, including party vote shares, constituency-level results, and regional electoral information. Data are available in machine-readable CSV and XML formats. Useful for analyzing Germany's contemporary party system, electoral geography, parliamentary representation, and political competition."
    },
    {
      "title": "Manifesto Project Dataset – Political Party Preferences and Electoral Programmes",
      "url_or_doi": "https://manifesto.wzb.eu/datasets/MPDS2026a",
      "justification": "International political party dataset maintained by the Manifesto Project at the Berlin Social Science Center (WZB). Contains systematic analyses of political party election manifestos, including German parties such as CDU/CSU, SPD, Greens, FDP, Die Linke, and AfD. Includes elections throughout the 2010s and 2020s. Enables research into ideological change, political polarization, party competition, and government policy priorities."
    },
    {
      "title": "Every Bundestag Vote Dataset – German Parliamentary Voting, 2017–2021",
      "url_or_doi": "https://doi.org/10.7910/DVN/LEOAHQ",
      "justification": "Research dataset published through Harvard Dataverse by Lukas Hohendorf, Ulrich Sieberer, and Jonas Wenzig. Contains information on every plenary vote, including recorded and non-recorded votes, in the German Bundestag during its 19th legislative period (2017–2021). Particularly relevant for investigating parliamentary decision-making, coalition politics, legislative opposition, government effectiveness, and voting behavior."
    },
    {
      "title": "German Election Results Since 1946 – Konrad Adenauer Foundation",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Historical electoral dataset maintained by the Konrad Adenauer Foundation. Provides German election results across multiple decades, including federal and regional elections during the 2010s and 2020s. Useful for longitudinal analysis of political parties, electoral participation, regional voting patterns, and institutional changes in Germany's democratic system."
    },
    {
      "title": "German Federal Election Results – Historical Bundestag Elections",
      "url_or_doi": "https://www.wahlen-in-deutschland.de/abbtwalg.htm?level=1",
      "justification": "Historical collection of German federal parliamentary election results, covering elections from 1949 through 2025. Includes party vote shares, parliamentary seat distribution, and detailed historical election information. Particularly useful for comparing the 2013, 2017, 2021, and 2025 elections and analyzing changes in party representation and the structure of Germany's parliamentary system."
    },
    {
      "title": "Small-Area Global Elections (SAGE) – Germany Election Results, 1998–2025",
      "url_or_doi": "https://sage-elections.com/germany/",
      "justification": "Electoral dataset containing geographically detailed German legislative election results. Covers eight federal elections between 1998 and 2025, including elections in 2013, 2017, 2021, and 2025. Particularly suitable for analyzing regional political differences, electoral geography, voting patterns, and the geographical distribution of support for German political parties."
    },
    {
      "title": "German Federal Election Data – Results, Constituency Boundaries and Polls",
      "url_or_doi": "https://www.pollingforecast.com/research/germany-data",
      "justification": "Harmonized collection of German federal election data covering 2005, 2009, 2013, 2017, 2021, and 2025. Includes first and second votes by political party, electoral constituencies, voter participation, geographical boundaries, and related polling information. Particularly useful for studying electoral system changes, constituency-level party competition, political representation, and long-term electoral trends."
    },
    {
      "title": "Manifesto Project Database – Political Party Programmes and Ideological Positions",
      "url_or_doi": "https://manifestoproject.wzb.eu/",
      "justification": "Research database containing quantitative analyses of political parties' electoral manifestos across numerous democracies, including Germany. Provides access to party policy positions, ideological classifications, and political programme information covering the 2010s and 2020s. Useful for analyzing German political organizations, party ideology, coalition compatibility, and changing policy agendas."
    },
    {
      "title": "German Longitudinal Election Study – Candidate and Nomination Studies",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "GESIS provides candidate-focused and nomination datasets associated with German elections, including nomination studies for 2021 and 2025 and candidate studies for European Parliament elections. These datasets support research on political recruitment, candidate selection, representation, party organizations, and electoral competition. Particularly relevant for understanding the internal functioning of political parties and parliamentary institutions during the 2020s."
    }
  ]
}
